class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        best = float('inf')

        def dfs(i, cur):
            nonlocal best
            if i == len(toppingCosts):
                d, bd = abs(cur - target), abs(best - target)
                if d < bd or (d == bd and cur < best):
                    best = cur
                return
            dfs(i + 1, cur)
            dfs(i + 1, cur + toppingCosts[i])
            dfs(i + 1, cur + 2 * toppingCosts[i])

        for b in baseCosts:
            dfs(0, b)
        return best

