class Solution {
    private int best = Integer.MAX_VALUE;

    public int closestCost(int[] baseCosts, int[] toppingCosts, int target) {
        for (int b : baseCosts) dfs(toppingCosts, 0, b, target);
        return best;
    }

    private void dfs(int[] t, int i, int cur, int target) {
        if (i == t.length) {
            int d = Math.abs(cur - target), bd = Math.abs(best - target);
            if (d < bd || (d == bd && cur < best)) best = cur;
            return;
        }
        dfs(t, i + 1, cur, target);
        dfs(t, i + 1, cur + t[i], target);
        dfs(t, i + 1, cur + 2 * t[i], target);
    }
};

