class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        sums = {0}
        for c in toppingCosts:
            sums = {s + k * c for s in sums for k in (0, 1, 2)}
        best = float('inf')
        for b in baseCosts:
            for s in sums:
                cand = b + s
                d, bd = abs(cand - target), abs(best - target)
                if d < bd or (d == bd and cand < best):
                    best = cand
        return best

