class Solution {
public:
    int closestCost(vector<int>& baseCosts, vector<int>& toppingCosts, int target) {
        unordered_set<int> sums{0};
        for (int c : toppingCosts) {
            unordered_set<int> nxt;
            for (int s : sums)
                for (int k = 0; k < 3; k++) nxt.insert(s + k * c);
            sums = move(nxt);
        }
        int best = INT_MAX;
        for (int b : baseCosts)
            for (int s : sums) {
                int cand = b + s;
                int d = abs(cand - target), bd = abs(best - target);
                if (d < bd || (d == bd && cand < best)) best = cand;
            }
        return best;
    }
};

