class Solution {
    public int closestCost(int[] baseCosts, int[] toppingCosts, int target) {
        Set<Integer> sums = new HashSet<>();
        sums.add(0);
        for (int c : toppingCosts) {
            Set<Integer> nxt = new HashSet<>();
            for (int s : sums)
                for (int k = 0; k < 3; k++) nxt.add(s + k * c);
            sums = nxt;
        }
        int best = Integer.MAX_VALUE;
        for (int b : baseCosts)
            for (int s : sums) {
                int cand = b + s;
                int d = Math.abs(cand - target), bd = Math.abs(best - target);
                if (d < bd || (d == bd && cand < best)) best = cand;
            }
        return best;
    }
};

